// Local preview IDs are monotonic text keys. API/SQL IDs are generated by SQL sequences.
let previewSequence = 0;
export const uid = () => {
    let next = previewSequence + 1;
    try {
        if (typeof globalThis.localStorage !== 'undefined') {
            next = Math.max(next, Number(globalThis.localStorage.getItem('workflow-preview-next-id') || 0) + 1);
            globalThis.localStorage.setItem('workflow-preview-next-id', String(next));
        }
    }
    catch { /* In tests/private browsing, continue with the in-memory counter. */ }
    previewSequence = next;
    return String(next);
};
export const niceDate = (d) => d ? new Date(d).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
export const initials = (name) => String(name || '?').split(/\s+/).slice(0, 2).map(p => p[0]).join('').toUpperCase();
export const slug = (value) => String(value || '').trim().toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 24);
export const saveCSV = (filename, headers, records) => {
    const csv = [headers.join(','), ...records.map(r => headers.map(h => `"${String(r[h] ?? '').replace(/"/g, '""')}"`).join(','))].join('\r\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
};
/** Project-owned lists and explicitly assigned global lists, including required global ancestors. */
export function availableLookups(state, project) {
    const lists = state.lookups || [];
    const byId = new Map(lists.map(l => [l.id, l]));
    const allowed = new Set(lists.filter(l => l.active !== false && (l.projectId === project?.id || (l.scope === 'global' && project?.lookupIds?.includes(l.id)))).map(l => l.id));
    // A selected child list requires its parent to populate cascading dropdowns.
    for (const id of [...allowed]) {
        const visited = new Set();
        let list = byId.get(id);
        while (list?.parentListId && !visited.has(list.id)) {
            visited.add(list.id);
            const parent = byId.get(list.parentListId);
            if (!parent || parent.active === false || !(parent.scope === 'global' || parent.projectId === project?.id))
                break;
            allowed.add(parent.id);
            list = parent;
        }
    }
    return lists.filter(l => allowed.has(l.id));
}
